<?php $title = 'Fidelidade — gestão Felito'; $redemptionStatus = ['pending' => 'Pendente', 'delivered' => 'Entregue', 'cancelled' => 'Cancelado']; ?>
<section class="content-layout manager-layout"><div class="manager-heading"><div><div class="eyebrow"><span class="dot"></span>Painel do gestor</div><h1>Fidelidade</h1><p>Configure a taxa de pontos, os brindes e os resgates.</p></div><?php require BASE_PATH . '/views/admin_nav.php'; ?></div>
  <div class="manager-grid"><section class="panel manager-form-panel"><h2>Taxa de acúmulo</h2><p class="muted-copy">Pontos creditados quando o pedido é marcado como entregue.</p><form method="post" class="form-stack"><?= csrfField() ?><input type="hidden" name="action" value="settings"><label for="points_per_real">Pontos por real</label><input id="points_per_real" name="points_per_real" type="number" min="0" max="1000" step="0.01" value="<?= e($settings['points_per_real'] ?? '1.00') ?>" required><button class="button button-primary" type="submit">Salvar taxa</button></form>
    <h2>Novo brinde</h2><form method="post" class="form-stack"><?= csrfField() ?><input type="hidden" name="action" value="reward"><label for="reward_name">Nome do brinde</label><input id="reward_name" name="name" maxlength="120" required><label for="reward_description">Descrição</label><textarea id="reward_description" name="description" maxlength="500" rows="3"></textarea><label for="points_cost">Custo em pontos</label><input id="points_cost" name="points_cost" type="number" min="1" max="10000000" required><button class="button button-primary" type="submit">Cadastrar brinde</button></form>
  </section><section class="panel manager-list-panel"><h2>Recompensas cadastradas</h2><?php if (!$rewards): ?><p class="muted-copy">Cadastre o primeiro brinde para os clientes.</p><?php else: ?><div class="movement-list"><?php foreach ($rewards as $reward): ?><article class="movement-row"><div class="movement-copy"><strong><?= e($reward['name']) ?> · <?= (int) $reward['points_cost'] ?> pontos</strong><p><?= e($reward['description']) ?></p><small><?= $reward['is_active'] ? 'Ativo' : 'Oculto' ?></small></div><?php if ($reward['is_active']): ?><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="deactivate"><input type="hidden" name="reward_id" value="<?= (int) $reward['id'] ?>"><button class="text-button danger-text" type="submit">Ocultar</button></form><?php endif ?></article><?php endforeach ?></div><?php endif ?></section></div>
  <section class="panel manager-list-panel"><h2>Resgates de clientes</h2><?php if (!$redemptions): ?><p class="muted-copy">Nenhum resgate solicitado.</p><?php else: ?><div class="movement-list"><?php foreach ($redemptions as $item): ?><article class="movement-row"><div class="movement-copy"><strong><?= e($item['reward_name']) ?> · <?= e($item['customer_name']) ?></strong><p><a href="mailto:<?= e($item['customer_email']) ?>"><?= e($item['customer_email']) ?></a> · <?= (int) $item['points_cost'] ?> pontos</p><small><?= e(localDateTime($item['created_at'])) ?> · <?= e($redemptionStatus[$item['status']] ?? $item['status']) ?></small></div><?php if ($item['status'] === 'pending'): ?><div class="inline-form"><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="delivered"><input type="hidden" name="redemption_id" value="<?= (int) $item['id'] ?>"><button class="button button-primary button-small" type="submit">Marcar entregue</button></form><form method="post" onsubmit="return confirm('Cancelar o resgate e devolver os pontos?')"><?= csrfField() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="redemption_id" value="<?= (int) $item['id'] ?>"><button class="button button-danger button-small" type="submit">Cancelar</button></form></div><?php endif ?></article><?php endforeach ?></div><?php endif ?></section>
</section>
